def task(robot):
    cans = robot.look()
    pepsi = next((c for c in cans if c["label"] == "Pepsi"), None)

    if not pepsi:
        robot.say("I don't see a Pepsi can.")
        return

    target = None
    min_dist = float('inf')

    for c in cans:
        if c["x"] < pepsi["x"]:
            dist = abs(c["x"] - pepsi["x"])
            if dist < min_dist:
                min_dist = dist
                target = c

    if target:
        robot.pick(target["id"])
        robot.give()
    else:
        robot.say("There is no can to the right of the Pepsi.")

def task(robot):
    robot.say("How many cans would you like?")
    request = robot.listen()
    try:
        count = int(request)
    except ValueError:
        count = 0

    cans = robot.look()
    cans.sort(key=lambda c: (c['x']**2 + c['y']**2))

    given = 0
    for can in cans:
        if given < count:
            if robot.pick(can['id']):
                robot.give()
                given += 1
        else:
            break

    if given < count:
        robot.say("That is all there is.")

def task(robot):
    cans = robot.look()
    if not cans:
        return

    counts = {}
    for c in cans:
        counts[c['colour']] = counts.get(c['colour'], 0) + 1

    most_common_colour = max(counts, key=counts.get)

    to_process = []
    for c in cans:
        if c['colour'] == most_common_colour:
            to_process.append(c)
        else:
            to_process.append(c)

    # Reorder to_process: most common first, then others
    sorted_cans = [c for c in cans if c['colour'] == most_common_colour]
    others = [c for c in cans if c['colour'] != most_common_colour]
    final_order = sorted_cans + others

    for can in final_order:
        if robot.pick(can['id']):
            robot.place("tray")

def task(robot):
